def single_number(nums):
    """
    Find the element that appears only once in an array of integers,
    where every other element appears twice.
    """
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
    for num, count in count.items():
        if count != 2:
            return num
    return None  # Should not happen with valid input
```

