def has_three_consecutive_identical_chars(s):
    """
    Given a string s, return True if the string contains at least one instance of three consecutive identical characters, and False otherwise.
    """
    count = [0] * 6
    for i in range(len(s) - 2):
        if s[i] == s[i+1] == s[i+2]:
            count[i+2] = 1
        elif s[i] == s[i+1]:
            count[i+1] += 1
        else:
            count[i+1] = 0
        if count[i+1] >= 3:
            return True

    return False
```

