def get_primes_desc(numbers: list) -> list:
    """
    Returns a list of all prime numbers from the input list, arranged in descending order.
    """
    primes = []
    for num in numbers:
        if num <= 1:
            continue
        if num <= 3:
            primes.append(num)
        elif num == 4:
            continue
        else:
            is_prime = True
            for divisor in range(2, int(num**0.5) + 1):
                if num % divisor == 0:
                    is_prime = False
                    break
            if is_prime:
                primes.append(num)
    return sorted(primes, reverse=True)
